select t.warehouse_id AS warehouseId, t.org_id AS orgId, t.sku_id AS skuId, t.sku_no AS skuNo, t.product_name AS productName, t.product_img_url AS productImgUrl, t.spu_no AS spuNo, t.sale_state AS saleState, t.usable_qty AS usableQty, t.frozen_qty AS frozenQty, t.intransit_qty AS intransitQty, t.waitqc_qty AS waitqcQty, t.real_qty AS realQty, t.warehouse_location AS warehouseLocation from ( select max(m.warehouse_location) AS warehouse_location, max(m.warehouse_id) as warehouse_id,max(m.org_id) as org_id,max(m.sku_id) as sku_id,max(m.sku_no) as sku_no,max(m.product_name) as product_name,max(m.product_img_url) as product_img_url,max(m.spu_no) as spu_no,max(m.sale_state) as sale_state, sum(m.usable_qty) as usable_qty,sum(m.frozen_qty) as frozen_qty,sum(m.intransit_qty) as intransit_qty,sum(m.waitqc_qty) as waitqc_qty,sum(m.usable_qty) + sum(m.frozen_qty) as real_qty from ( select max(it.warehouse_id) as warehouse_id, max(it.org_id) as org_id, max(it.sku_id) as sku_id, max(it.sku_no) as sku_no, max(pd.name) as product_name, max(pd.images_url) as product_img_url, max(pi.spu_no) as spu_no, max(ps.sale_state) as sale_state, max(it.warehouse_location) AS warehouse_location, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usable_qty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozen_qty, sum(case when it.dict_inventory_status = 'inTransit' then it.qty else 0 end) as intransit_qty, sum(case when it.dict_inventory_status = 'waitQc' then it.qty else 0 end) as waitqc_qty from inventory it left join product_detail pd on pd.id = it.sku_id AND pd.is_deleted = FALSE left join product_info pi on pd.product_id = pi.id AND pi.is_deleted = FALSE left join product_sale ps on ps.sku_id = pd.id AND ps.is_deleted = FALSE
it.is_deleted = false
and pd.name ILIKE concat('%', #{params.productName}::text ,'%')
and it.sku_no in
#{item}
and pi.spu_no in
#{item}
and ps.sale_state in
#{item}
and it.warehouse_id in
#{item}
and it.org_id in
#{item}
${params.permissionSql}
group by it.warehouse_id,it.org_id,it.sku_id,it.dict_inventory_status,it.warehouse_location ) m group by m.warehouse_id,m.org_id,m.sku_id,m.warehouse_location ) t
and t.real_qty != 0
order by
${item.field} ${item.sort}
t.sku_no, t.warehouse_id

