select warehouse_id,org_id,sku_id,max(sku_no) as sku_no,warehouse_location,max(spu_no) as spu_no,max(sale_state) as sale_state, SUM (qty) AS real_inventory, SUM (usable_inventory) AS usable_inventory
sum(case when age >= #{item.startValue}
and age < #{item.endValue}
then qty else 0 end) as "${item.name}"
from ( SELECT max(inv.warehouse_id) as warehouse_id, max(inv.org_id) as org_id, max(inv.sku_id) as sku_id, max(inv.sku_no) as sku_no, max(inv.warehouse_location) as warehouse_location, max(ind.instock_batch_date) as instock_batch_date, date_part( 'day', CURRENT_DATE :: TIMESTAMP - max(ind.instock_batch_date) :: TIMESTAMP ) AS age, sum(ind.qty) qty, sum(case when inv.dict_inventory_status = 'usable' then ind.qty else 0 end) as usable_inventory, max(pi.spu_no) AS spu_no, max(ps.sale_state) AS sale_state FROM inventory_detail ind INNER JOIN inventory inv ON ind.info_id = inv.id left join product_detail pd on pd.id = inv.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id WHERE ind.is_deleted = false AND inv.dict_inventory_status in('usable','frozen') AND ind.qty != 0
and inv.sku_no in
#{item}
and pi.spu_no in
#{item}
and inv.warehouse_id in
#{item}
and inv.org_id in
#{item}
and inv.warehouse_location in
#{item}
${params.permissionSql}
group by inv.warehouse_id,inv.org_id,inv.sku_id,inv.warehouse_location,ind.instock_batch_date ) m group by warehouse_id,org_id,sku_id,warehouse_location order by real_inventory desc

select warehouse_id,org_id,sku_id,max(sku_no) as sku_no,warehouse_location,max(spu_no) as spu_no,max(sale_state) as sale_state, SUM (qty) AS real_inventory, SUM (usable_inventory) AS usable_inventory
sum(case when age >= #{item.startValue}
and age < #{item.endValue}
then qty else 0 end) as "${item.name}"
from ( SELECT max(inv.warehouse_id) as warehouse_id, max(inv.org_id) as org_id, max(inv.sku_id) as sku_id, max(inv.sku_no) as sku_no, max(inv.warehouse_location) as warehouse_location, max(ind.instock_batch_date) as instock_batch_date, date_part( 'day', CURRENT_DATE :: TIMESTAMP - max(ind.instock_batch_date) :: TIMESTAMP ) AS age, sum(ind.qty) qty, sum(case when inv.dict_inventory_status = 'usable' then ind.qty else 0 end) as usable_inventory, max(pi.spu_no) AS spu_no, max(ps.sale_state) AS sale_state FROM inventory_detail ind INNER JOIN inventory inv ON ind.info_id = inv.id left join product_detail pd on pd.id = inv.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id WHERE ind.is_deleted = false AND inv.dict_inventory_status in('usable','frozen') AND ind.qty != 0
and inv.sku_id in
#{item}
and inv.sku_no in
#{item}
and pi.spu_no in
#{item}
and inv.warehouse_id in
#{item}
and inv.org_id in
#{item}
and inv.warehouse_location in
#{item}
${params.permissionSql}
group by inv.warehouse_id,inv.org_id,inv.sku_id,inv.warehouse_location,ind.instock_batch_date ) m group by warehouse_id,org_id,sku_id,warehouse_location order by real_inventory desc

SELECT t.warehouse_id, t.usableQty, tt.todayStockInQty, tt.todayDeliveryQty FROM ( SELECT i.warehouse_id, SUM(qty) AS usableQty FROM inventory i WHERE is_deleted = FALSE
AND dict_inventory_status = #{status}
AND warehouse_id = #{warehouseId}
GROUP BY i.warehouse_id )t LEFT JOIN ( SELECT warehouse_id, SUM(CASE WHEN qty > 0 THEN qty END) AS todayStockInQty, SUM(CASE WHEN qty < 0 THEN qty END) AS todayDeliveryQty FROM "transaction_flow" WHERE to_char(create_time,'YYYY-MM-dd') = to_char(NOW()::timestamp,'YYYY-MM-dd') AND is_unapproved = FALSE
AND dict_inventory_status = #{status}
AND warehouse_id = #{warehouseId}
AND dict_inventory_status = 'usable' GROUP BY warehouse_id )tt ON t.warehouse_id = tt.warehouse_id

SELECT it.warehouse_id, it.sku_id, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) + sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as realQty, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usableQty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozenQty, sum(case when it.dict_inventory_status = 'inTransit' then it.qty else 0 end) as intransitQty, sum(case when it.dict_inventory_status = 'waitQc' then it.qty else 0 end) as waitqcQty FROM "inventory" it WHERE it.is_deleted = FALSE
and it.sku_id = #{params.skuId}
and it.warehouse_location = #{params.warehouseLocation}
and it.warehouse_id = #{params.warehouseId}
GROUP BY it.warehouse_id, it.sku_id

mapper.sql:
SELECT t.warehouse_id, t.sku_id, t.realQty, t.usableQty, t.frozenQty, t.intransitQty, t.waitqcQty FROM ( SELECT it.warehouse_id, it.sku_id, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) + sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as realQty, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usableQty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozenQty, sum(case when it.dict_inventory_status = 'inTransit' then it.qty else 0 end) as intransitQty, sum(case when it.dict_inventory_status = 'waitQc' then it.qty else 0 end) as waitqcQty FROM "inventory" it WHERE it.is_deleted = FALSE
and it.sku_id = #{params.skuId}
AND it.sku_id IN
#{item}
and it.sku_no = #{params.skuNo}
and it.warehouse_id = #{params.warehouseId}
and it.org_id in #{params.orgId}
and it.org_id in
#{orgId}
and exists (select 1 from warehouse wh where wh.id = it.warehouse_id and wh.warehouse_manage_type = 'selfBuild')
and it.warehouse_location = #{params.warehouseLocation}
GROUP BY it.warehouse_id, it.sku_id ) t
WHERE t.realQty > 0

mapper.select:
SELECT t.sku_id, t.realQty, t.usableQty, t.frozenQty, t.intransitQty, t.waitqcQty FROM ( SELECT it.sku_id, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) + sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as realQty, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usableQty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozenQty, sum(case when it.dict_inventory_status = 'inTransit' then it.qty else 0 end) as intransitQty, sum(case when it.dict_inventory_status = 'waitQc' then it.qty else 0 end) as waitqcQty FROM "inventory" it WHERE it.is_deleted = FALSE and it.warehouse_location is not null and it.warehouse_location != ''
and it.sku_id = #{params.skuId}
and it.sku_no = #{params.skuNo}
and it.warehouse_id = #{params.warehouseId}
and it.org_id in #{params.orgId}
and it.org_id in
#{orgId}
and exists (select 1 from warehouse wh where wh.id = it.warehouse_id and wh.warehouse_manage_type = 'selfBuild')
and it.warehouse_location = #{params.warehouseLocation}
GROUP BY it.sku_id ) t
WHERE t.realQty > 0

SELECT t.warehouse_id, t.sku_id, t.realQty, t.usableQty, t.frozenQty, t.intransitQty, t.waitqcQty FROM ( SELECT it.warehouse_id, it.sku_id, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) + sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as realQty, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usableQty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozenQty, sum(case when it.dict_inventory_status = 'inTransit' then it.qty else 0 end) as intransitQty, sum(case when it.dict_inventory_status = 'waitQc' then it.qty else 0 end) as waitqcQty FROM "inventory" it WHERE it.is_deleted = FALSE and it.warehouse_location is not null and it.warehouse_location != ''
and it.sku_id = #{params.skuId}
AND it.sku_id IN
#{item}
and it.sku_no = #{params.skuNo}
and it.warehouse_id = #{params.warehouseId}
and it.org_id in #{params.orgId}
and it.org_id in
#{orgId}
and exists (select 1 from warehouse wh where wh.id = it.warehouse_id and wh.warehouse_manage_type = 'selfBuild')
and it.warehouse_location = #{params.warehouseLocation}
GROUP BY it.warehouse_id, it.sku_id ) t WHERE t.realQty > 0

SELECT t.warehouse_id, t.org_id, t.sku_id, t.warehouse_location, t.realQty, t.usableQty, t.frozenQty, t.intransitQty, t.waitqcQty FROM ( SELECT it.warehouse_id, it.org_id, it.sku_id, it.warehouse_location, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) + sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as realQty, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usableQty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozenQty, sum(case when it.dict_inventory_status = 'inTransit' then it.qty else 0 end) as intransitQty, sum(case when it.dict_inventory_status = 'waitQc' then it.qty else 0 end) as waitqcQty FROM "inventory" it WHERE it.is_deleted = FALSE
and it.sku_id = #{params.skuId}
and it.sku_no = #{params.skuNo}
and it.warehouse_id = #{params.warehouseId}
and it.org_id in #{params.orgId}
and it.org_id in
#{orgId}
and exists (select 1 from warehouse wh where wh.id = it.warehouse_id and wh.warehouse_manage_type = 'selfBuild')
and it.warehouse_location = #{params.warehouseLocation}
GROUP BY it.warehouse_id, it.org_id, it.sku_id, it.warehouse_location ) t WHERE t.realQty > 0

SELECT inv.org_id, inv.warehouse_id, inv.warehouse_location, inv.sku_id, inv.sku_no, inv.dict_inventory_status, sum(inv.qty) AS qty FROM inventory inv WHERE is_deleted=FALSE
and inv.sku_id in
#{skuId}
and inv.sku_no in
#{skuNo}
and inv.warehouse_id in
#{warehouseId}
and inv.warehouse_location in
#{warehouseLocation}
and inv.org_id in
#{orgId}
GROUP BY inv.org_id, inv.warehouse_id, inv.warehouse_location, inv.sku_id, inv.sku_no, inv.dict_inventory_status

SELECT it.warehouse_id, it.sku_id, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usableQty FROM "inventory" it WHERE it.is_deleted = FALSE and it.sku_id in
#{skuId}
and it.warehouse_id in
#{warehouseId}
GROUP BY it.warehouse_id, it.sku_id

select t.warehouse_id AS warehouseId, t.org_id AS orgId, t.sku_id AS skuId, t.sku_no AS skuNo, t.product_name AS productName, t.product_img_url AS productImgUrl, t.spu_no AS spuNo, t.sale_state AS saleState, t.usable_qty AS usableQty, t.frozen_qty AS frozenQty, t.real_qty AS realQty, t.area_code AS warehouseArea from (select max(m.warehouse_id) as warehouse_id, max(m.org_id) as org_id, max(m.sku_id) as sku_id, max(m.sku_no) as sku_no, max(m.product_name) as product_name, max(m.product_img_url) as product_img_url, max(m.spu_no) as spu_no, max(m.sale_state) as sale_state, max(m.area_code) as area_code, sum(m.usable_qty) as usable_qty, sum(m.frozen_qty) as frozen_qty, sum(m.usable_qty) + sum(m.frozen_qty) as real_qty from (select max(it.warehouse_id) as warehouse_id, max(it.org_id) as org_id, max(it.sku_id) as sku_id, max(it.sku_no) as sku_no, max(pd.name) as product_name, max(pd.images_url) as product_img_url, max(pi.spu_no) as spu_no, max(ps.sale_state) as sale_state, max(wl.area_code) as area_code, sum(case when it.dict_inventory_status = 'usable' then it.qty else 0 end) as usable_qty, sum(case when it.dict_inventory_status = 'frozen' then it.qty else 0 end) as frozen_qty from inventory it left join product_detail pd on pd.id = it.sku_id AND pd.is_deleted = FALSE left join product_info pi on pd.product_id = pi.id AND pi.is_deleted = FALSE left join product_sale ps on ps.sku_id = pd.id AND ps.is_deleted = FALSE left join (select distinct s.code as location_code, wa.code as area_code, s.warehouse_id, wa.name as area_name from warehouse_location s left join warehouse_location wa on s.parent_id = wa.id and s.is_deleted = false and wa.is_deleted = false) wl on it.warehouse_location = wl.location_code and it.warehouse_id = wl.warehouse_id
it.is_deleted = false
and pd.name ILIKE concat('%', #{params.productName}::text ,'%')
and it.sku_no in
#{item}
and it.sku_id in
#{item}
and pi.spu_no in
#{item}
and ps.sale_state in
#{item}
and it.warehouse_id in
#{item}
and it.org_id in
#{item}
and wl.area_name = #{params.warehouseAreaName}
${params.permissionSql}
group by it.warehouse_id, it.org_id, it.sku_id, it.dict_inventory_status, wl.area_code) m group by m.warehouse_id, m.org_id, m.sku_id, m.area_code) t
and t.real_qty != 0
order by
